def test_seesaw_loss():
    with pytest.raises(AssertionError):
        loss_cfg = dict(type='SeesawLoss', use_sigmoid=True, loss_weight=1.0)
        build_loss(loss_cfg)
    loss_cls_cfg = dict(type='SeesawLoss', p=0.0, q=0.0, loss_weight=1.0, num_classes=2)
    loss_cls = build_loss(loss_cls_cfg)
    with pytest.raises(AssertionError):
        fake_pred = torch.Tensor([[-100, 100]])
        fake_label = torch.Tensor([1]).long()
        loss_cls(fake_pred, fake_label)
    with pytest.raises(AssertionError):
        fake_pred = torch.Tensor([[-100, 100, -100]])
        fake_label = torch.Tensor([1]).long()
        loss_cls(fake_pred, fake_label)
    loss_cls_cfg = dict(type='SeesawLoss', p=0.0, q=0.0, loss_weight=1.0, num_classes=2)
    loss_cls = build_loss(loss_cls_cfg)
    fake_pred = torch.Tensor([[-100, 100, -100, 100]])
    fake_label = torch.Tensor([1]).long()
    loss = loss_cls(fake_pred, fake_label)
    assert torch.allclose(loss['loss_cls_objectness'], torch.tensor(200.0))
    assert torch.allclose(loss['loss_cls_classes'], torch.tensor(0.0))
    loss_cls_cfg = dict(type='SeesawLoss', p=1.0, q=0.0, loss_weight=1.0, num_classes=2)
    loss_cls = build_loss(loss_cls_cfg)
    fake_pred = torch.Tensor([[-100, 100, -100, 100]])
    fake_label = torch.Tensor([0]).long()
    loss_cls.cum_samples[0] = torch.exp(torch.Tensor([20]))
    loss = loss_cls(fake_pred, fake_label)
    assert torch.allclose(loss['loss_cls_objectness'], torch.tensor(200.0))
    assert torch.allclose(loss['loss_cls_classes'], torch.tensor(180.0))
    loss_cls_cfg = dict(type='SeesawLoss', p=0.0, q=1.0, loss_weight=1.0, num_classes=2)
    loss_cls = build_loss(loss_cls_cfg)
    fake_pred = torch.Tensor([[-100, 100, -100, 100]])
    fake_label = torch.Tensor([0]).long()
    loss = loss_cls(fake_pred, fake_label)
    assert torch.allclose(loss['loss_cls_objectness'], torch.tensor(200.0))
    assert torch.allclose(loss['loss_cls_classes'], torch.tensor(200.0) + torch.tensor(100.0).log())
    loss_cls_cfg = dict(type='SeesawLoss', p=0.0, q=1.0, loss_weight=1.0, num_classes=2, return_dict=False)
    loss_cls = build_loss(loss_cls_cfg)
    fake_pred = torch.Tensor([[100, -100, 100, -100]])
    fake_label = torch.Tensor([0]).long()
    loss = loss_cls(fake_pred, fake_label)
    acc = loss_cls.get_accuracy(fake_pred, fake_label)
    act = loss_cls.get_activation(fake_pred)
    assert torch.allclose(loss, torch.tensor(0.0))
    assert torch.allclose(acc['acc_objectness'], torch.tensor(100.0))
    assert torch.allclose(acc['acc_classes'], torch.tensor(100.0))
    assert torch.allclose(act, torch.tensor([1.0, 0.0, 0.0]))

def test_accuracy():
    pred = torch.empty(0, 4)
    label = torch.empty(0)
    accuracy = Accuracy(topk=1)
    acc = accuracy(pred, label)
    assert acc.item() == 0
    pred = torch.Tensor([[0.2, 0.3, 0.6, 0.5], [0.1, 0.1, 0.2, 0.6], [0.9, 0.0, 0.0, 0.1], [0.4, 0.7, 0.1, 0.1], [0.0, 0.0, 0.99, 0]])
    true_label = torch.Tensor([2, 3, 0, 1, 2]).long()
    accuracy = Accuracy(topk=1)
    acc = accuracy(pred, true_label)
    assert acc.item() == 100
    true_label = torch.Tensor([2, 3, 0, 1, 2]).long()
    accuracy = Accuracy(topk=1, thresh=0.8)
    acc = accuracy(pred, true_label)
    assert acc.item() == 40
    accuracy = Accuracy(topk=2)
    label = torch.Tensor([3, 2, 0, 0, 2]).long()
    acc = accuracy(pred, label)
    assert acc.item() == 100
    accuracy = Accuracy(topk=(1, 2))
    true_label = torch.Tensor([2, 3, 0, 1, 2]).long()
    acc = accuracy(pred, true_label)
    for a in acc:
        assert a.item() == 100
    with pytest.raises(AssertionError):
        accuracy = Accuracy(topk=5)
        accuracy(pred, true_label)
    with pytest.raises(AssertionError):
        accuracy = Accuracy(topk='wrong type')
        accuracy(pred, true_label)
    with pytest.raises(AssertionError):
        label = torch.Tensor([2, 3, 0, 1, 2, 0]).long()
        accuracy = Accuracy()
        accuracy(pred, label)
    with pytest.raises(AssertionError):
        accuracy = Accuracy()
        accuracy(pred[:, :, None], true_label)

def _demo_mm_inputs(input_shape=(1, 3, 300, 300), num_items=None, num_classes=10, with_track=False):
    """Create a superset of inputs needed to run test or train batches.

    Args:
        input_shape (tuple):
            input batch dimensions

        num_items (None | List[int]):
            specifies the number of boxes in each batch item

        num_classes (int):
            number of different labels a box might have
    """
    from mmdet.core import BitmapMasks
    N, C, H, W = input_shape
    rng = np.random.RandomState(0)
    imgs = rng.rand(*input_shape)
    img_metas = [{'img_shape': (H, W, C), 'ori_shape': (H, W, C), 'pad_shape': (H, W, C), 'filename': '<demo>.png', 'scale_factor': 1.0, 'flip': False, 'frame_id': 0, 'img_norm_cfg': {'mean': (128.0, 128.0, 128.0), 'std': (10.0, 10.0, 10.0)}} for i in range(N)]
    gt_bboxes = []
    gt_labels = []
    gt_masks = []
    gt_match_indices = []
    for batch_idx in range(N):
        if num_items is None:
            num_boxes = rng.randint(1, 10)
        else:
            num_boxes = num_items[batch_idx]
        cx, cy, bw, bh = rng.rand(num_boxes, 4).T
        tl_x = (cx * W - W * bw / 2).clip(0, W)
        tl_y = (cy * H - H * bh / 2).clip(0, H)
        br_x = (cx * W + W * bw / 2).clip(0, W)
        br_y = (cy * H + H * bh / 2).clip(0, H)
        boxes = np.vstack([tl_x, tl_y, br_x, br_y]).T
        class_idxs = rng.randint(1, num_classes, size=num_boxes)
        gt_bboxes.append(torch.FloatTensor(boxes))
        gt_labels.append(torch.LongTensor(class_idxs))
        if with_track:
            gt_match_indices.append(torch.arange(boxes.shape[0]))
    mask = np.random.randint(0, 2, (len(boxes), H, W), dtype=np.uint8)
    gt_masks.append(BitmapMasks(mask, H, W))
    mm_inputs = {'imgs': torch.FloatTensor(imgs).requires_grad_(True), 'img_metas': img_metas, 'gt_bboxes': gt_bboxes, 'gt_labels': gt_labels, 'gt_bboxes_ignore': None, 'gt_masks': gt_masks}
    if with_track:
        mm_inputs['gt_match_indices'] = gt_match_indices
    return mm_inputs

class Model(nn.Module):

    def __init__(self):
        super().__init__()
        self.linear = nn.Linear(2, 1)
        self.conv = nn.Conv2d(3, 3, 3)

    def forward(self, x):
        return self.linear(x)

    def train_step(self, x, optimizer, **kwargs):
        return dict(loss=self(x))

    def val_step(self, x, optimizer, **kwargs):
        return dict(loss=self(x))

def train_step(self, x, optimizer, **kwargs):
    return dict(loss=self(x))

def val_step(self, x, optimizer, **kwargs):
    return dict(loss=self(x))

class DemoModel(nn.Module):

    def __init__(self):
        super().__init__()
        self.epoch = 0
        self.linear = nn.Linear(2, 1)

    def forward(self, x):
        return self.linear(x)

    def train_step(self, x, optimizer, **kwargs):
        return dict(loss=self(x))

    def set_epoch(self, epoch):
        self.epoch = epoch

def train_step(self, x, optimizer, **kwargs):
    return dict(loss=self(x))

def val_step(self, x, optimizer, **kwargs):
    return dict(loss=self(x))

def _create_mask(N, h, w):
    masks = torch.rand((N, h, w)) > 0.5
    labels = torch.rand(N)
    scores = torch.rand(N)
    return (masks, labels, scores)

def test_nms_input_errors():
    with pytest.raises(AssertionError):
        mask_matrix_nms(torch.rand((10, 28, 28)), torch.rand(11), torch.rand(11))
    with pytest.raises(AssertionError):
        masks = torch.rand((10, 28, 28))
        mask_matrix_nms(masks, torch.rand(11), torch.rand(11), mask_area=masks.sum((1, 2)).float()[:8])
    with pytest.raises(NotImplementedError):
        mask_matrix_nms(torch.rand((10, 28, 28)), torch.rand(10), torch.rand(10), kernel='None')
    masks, labels, scores = _create_mask(0, 28, 28)
    score, label, mask, keep_ind = mask_matrix_nms(masks, labels, scores)
    assert len(score) == len(label) == len(mask) == len(keep_ind) == 0
    masks, labels, scores = _create_mask(1000, 28, 28)
    score, label, mask, keep_ind = mask_matrix_nms(masks, labels, scores)
    assert len(score) == len(label) == len(mask) == len(keep_ind) == 1000
    score, label, mask, keep_ind = mask_matrix_nms(masks, labels, scores, nms_pre=500)
    assert len(score) == len(label) == len(mask) == len(keep_ind) == 500
    score, label, mask, keep_ind = mask_matrix_nms(masks, labels, scores, nms_pre=500, max_num=100)
    assert len(score) == len(label) == len(mask) == len(keep_ind) == 100
    masks, labels, _ = _create_mask(1, 28, 28)
    scores = torch.Tensor([1.0])
    masks = masks.expand(1000, 28, 28)
    labels = labels.expand(1000)
    scores = scores.expand(1000)
    score, label, mask, keep_ind = mask_matrix_nms(masks, labels, scores, nms_pre=500, max_num=100, kernel='gaussian', sigma=2.0, filter_thr=0.5)
    assert len(score) == 1
    assert score[0] == 1

def test_sparse_prior():
    from mmdet.core.anchor import MlvlPointGenerator
    mlvl_points = MlvlPointGenerator(strides=[4, 10], offset=0)
    prior_indexs = torch.Tensor([0, 2, 4, 5, 6, 9]).long()
    featmap_sizes = [(3, 5), (6, 4)]
    grid_anchors = mlvl_points.grid_priors(featmap_sizes=featmap_sizes, with_stride=False, device='cpu')
    sparse_prior = mlvl_points.sparse_priors(prior_idxs=prior_indexs, featmap_size=featmap_sizes[0], level_idx=0, device='cpu')
    assert not sparse_prior.is_cuda
    assert (sparse_prior == grid_anchors[0][prior_indexs]).all()
    sparse_prior = mlvl_points.sparse_priors(prior_idxs=prior_indexs, featmap_size=featmap_sizes[1], level_idx=1, device='cpu')
    assert (sparse_prior == grid_anchors[1][prior_indexs]).all()
    from mmdet.core.anchor import AnchorGenerator
    mlvl_anchors = AnchorGenerator(strides=[16, 32], ratios=[1.0], scales=[1.0], base_sizes=[4, 8])
    prior_indexs = torch.Tensor([0, 2, 4, 5, 6, 9]).long()
    featmap_sizes = [(3, 5), (6, 4)]
    grid_anchors = mlvl_anchors.grid_priors(featmap_sizes=featmap_sizes, device='cpu')
    sparse_prior = mlvl_anchors.sparse_priors(prior_idxs=prior_indexs, featmap_size=featmap_sizes[0], level_idx=0, device='cpu')
    assert (sparse_prior == grid_anchors[0][prior_indexs]).all()
    sparse_prior = mlvl_anchors.sparse_priors(prior_idxs=prior_indexs, featmap_size=featmap_sizes[1], level_idx=1, device='cpu')
    assert (sparse_prior == grid_anchors[1][prior_indexs]).all()
    from mmdet.core.anchor.anchor_generator import SSDAnchorGenerator
    featmap_sizes = [(38, 38), (19, 19), (10, 10)]
    anchor_generator = SSDAnchorGenerator(scale_major=False, input_size=300, basesize_ratio_range=(0.15, 0.9), strides=[8, 16, 32], ratios=[[2], [2, 3], [2, 3]])
    ssd_anchors = anchor_generator.grid_anchors(featmap_sizes, device='cpu')
    for i in range(len(featmap_sizes)):
        sparse_ssd_anchors = anchor_generator.sparse_priors(prior_idxs=prior_indexs, level_idx=i, featmap_size=featmap_sizes[i], device='cpu')
        assert (sparse_ssd_anchors == ssd_anchors[i][prior_indexs]).all()
    from mmdet.core.anchor.anchor_generator import YOLOAnchorGenerator
    featmap_sizes = [(38, 38), (19, 19), (10, 10)]
    anchor_generator = YOLOAnchorGenerator(strides=[32, 16, 8], base_sizes=[[(116, 90), (156, 198), (373, 326)], [(30, 61), (62, 45), (59, 119)], [(10, 13), (16, 30), (33, 23)]])
    yolo_anchors = anchor_generator.grid_anchors(featmap_sizes, device='cpu')
    for i in range(len(featmap_sizes)):
        sparse_yolo_anchors = anchor_generator.sparse_priors(prior_idxs=prior_indexs, level_idx=i, featmap_size=featmap_sizes[i], device='cpu')
        assert (sparse_yolo_anchors == yolo_anchors[i][prior_indexs]).all()
    if torch.cuda.is_available():
        mlvl_points = MlvlPointGenerator(strides=[4, 10], offset=0)
        prior_indexs = torch.Tensor([0, 3, 4, 5, 6, 7, 1, 2, 4, 5, 6, 9]).long().cuda()
        featmap_sizes = [(6, 8), (6, 4)]
        grid_anchors = mlvl_points.grid_priors(featmap_sizes=featmap_sizes, with_stride=False, device='cuda')
        sparse_prior = mlvl_points.sparse_priors(prior_idxs=prior_indexs, featmap_size=featmap_sizes[0], level_idx=0, device='cuda')
        assert (sparse_prior == grid_anchors[0][prior_indexs]).all()
        sparse_prior = mlvl_points.sparse_priors(prior_idxs=prior_indexs, featmap_size=featmap_sizes[1], level_idx=1, device='cuda')
        assert (sparse_prior == grid_anchors[1][prior_indexs]).all()
        assert sparse_prior.is_cuda
        mlvl_anchors = AnchorGenerator(strides=[16, 32], ratios=[1.0, 2.5], scales=[1.0, 5.0], base_sizes=[4, 8])
        prior_indexs = torch.Tensor([4, 5, 6, 7, 0, 2, 50, 4, 5, 6, 9]).long().cuda()
        featmap_sizes = [(13, 5), (16, 4)]
        grid_anchors = mlvl_anchors.grid_priors(featmap_sizes=featmap_sizes, device='cuda')
        sparse_prior = mlvl_anchors.sparse_priors(prior_idxs=prior_indexs, featmap_size=featmap_sizes[0], level_idx=0, device='cuda')
        assert (sparse_prior == grid_anchors[0][prior_indexs]).all()
        sparse_prior = mlvl_anchors.sparse_priors(prior_idxs=prior_indexs, featmap_size=featmap_sizes[1], level_idx=1, device='cuda')
        assert (sparse_prior == grid_anchors[1][prior_indexs]).all()
        from mmdet.core.anchor.anchor_generator import SSDAnchorGenerator
        featmap_sizes = [(38, 38), (19, 19), (10, 10)]
        anchor_generator = SSDAnchorGenerator(scale_major=False, input_size=300, basesize_ratio_range=(0.15, 0.9), strides=[8, 16, 32], ratios=[[2], [2, 3], [2, 3]])
        ssd_anchors = anchor_generator.grid_anchors(featmap_sizes, device='cuda')
        for i in range(len(featmap_sizes)):
            sparse_ssd_anchors = anchor_generator.sparse_priors(prior_idxs=prior_indexs, level_idx=i, featmap_size=featmap_sizes[i], device='cuda')
            assert (sparse_ssd_anchors == ssd_anchors[i][prior_indexs]).all()
        from mmdet.core.anchor.anchor_generator import YOLOAnchorGenerator
        featmap_sizes = [(38, 38), (19, 19), (10, 10)]
        anchor_generator = YOLOAnchorGenerator(strides=[32, 16, 8], base_sizes=[[(116, 90), (156, 198), (373, 326)], [(30, 61), (62, 45), (59, 119)], [(10, 13), (16, 30), (33, 23)]])
        yolo_anchors = anchor_generator.grid_anchors(featmap_sizes, device='cuda')
        for i in range(len(featmap_sizes)):
            sparse_yolo_anchors = anchor_generator.sparse_priors(prior_idxs=prior_indexs, level_idx=i, featmap_size=featmap_sizes[i], device='cuda')
            assert (sparse_yolo_anchors == yolo_anchors[i][prior_indexs]).all()

def test_standard_anchor_generator():
    from mmdet.core.anchor import build_anchor_generator
    anchor_generator_cfg = dict(type='AnchorGenerator', scales=[8], ratios=[0.5, 1.0, 2.0], strides=[4, 8])
    anchor_generator = build_anchor_generator(anchor_generator_cfg)
    assert anchor_generator.num_base_priors == anchor_generator.num_base_anchors
    assert anchor_generator.num_base_priors == [3, 3]
    assert anchor_generator is not None

def test_strides():
    from mmdet.core import AnchorGenerator
    self = AnchorGenerator([10], [1.0], [1.0], [10])
    anchors = self.grid_anchors([(2, 2)], device='cpu')
    expected_anchors = torch.tensor([[-5.0, -5.0, 5.0, 5.0], [5.0, -5.0, 15.0, 5.0], [-5.0, 5.0, 5.0, 15.0], [5.0, 5.0, 15.0, 15.0]])
    assert torch.equal(anchors[0], expected_anchors)
    self = AnchorGenerator([(10, 20)], [1.0], [1.0], [10])
    anchors = self.grid_anchors([(2, 2)], device='cpu')
    expected_anchors = torch.tensor([[-5.0, -5.0, 5.0, 5.0], [5.0, -5.0, 15.0, 5.0], [-5.0, 15.0, 5.0, 25.0], [5.0, 15.0, 15.0, 25.0]])
    assert torch.equal(anchors[0], expected_anchors)

