def test_filter_scores_and_topk():
    score = torch.tensor([[0.1, 0.3, 0.2], [0.12, 0.7, 0.9], [0.02, 0.8, 0.08], [0.4, 0.1, 0.08]])
    bbox_pred = torch.tensor([[0.2, 0.3], [0.4, 0.7], [0.1, 0.1], [0.5, 0.1]])
    score_thr = 0.15
    nms_pre = 4
    with pytest.raises(NotImplementedError):
        filter_scores_and_topk(score, score_thr, nms_pre, (score,))
    filtered_results = filter_scores_and_topk(score, score_thr, nms_pre, results=dict(bbox_pred=bbox_pred))
    filtered_score, labels, keep_idxs, results = filtered_results
    assert filtered_score.allclose(torch.tensor([0.9, 0.8, 0.7, 0.4]))
    assert labels.allclose(torch.tensor([2, 1, 1, 0]))
    assert keep_idxs.allclose(torch.tensor([1, 2, 1, 3]))
    assert results['bbox_pred'].allclose(torch.tensor([[0.4, 0.7], [0.1, 0.1], [0.4, 0.7], [0.5, 0.1]]))

def test_avoidoom():
    tensor = torch.from_numpy(np.random.random((20, 20)))
    if torch.cuda.is_available():
        tensor = tensor.cuda()
        default_result = torch.mm(tensor, tensor.transpose(1, 0))
        AvoidCudaOOM = AvoidOOM()
        result = AvoidCudaOOM.retry_if_cuda_oom(torch.mm)(tensor, tensor.transpose(1, 0))
        assert default_result.device == result.device and default_result.dtype == result.dtype and torch.equal(default_result, result)
        AvoidCudaOOM = AvoidOOM(test=True)
        result = AvoidCudaOOM.retry_if_cuda_oom(torch.mm)(tensor, tensor.transpose(1, 0))
        assert default_result.device == result.device and default_result.dtype == result.dtype and torch.allclose(default_result, result, 0.001)
        AvoidCudaOOM = AvoidOOM(test=True)
        result = AvoidCudaOOM.retry_if_cuda_oom(torch.mm)(tensor, tensor.transpose(1, 0))
        assert result.dtype == default_result.dtype and result.device == default_result.device and torch.allclose(default_result, result)
        AvoidCudaOOM = AvoidOOM(test=True, to_cpu=False)
        result = AvoidCudaOOM.retry_if_cuda_oom(torch.mm)(tensor, tensor.transpose(1, 0))
        assert result.dtype == default_result.dtype and result.device == default_result.device
    else:
        default_result = torch.mm(tensor, tensor.transpose(1, 0))
        AvoidCudaOOM = AvoidOOM()
        result = AvoidCudaOOM.retry_if_cuda_oom(torch.mm)(tensor, tensor.transpose(1, 0))
        assert default_result.device == result.device and default_result.dtype == result.dtype and torch.equal(default_result, result)

def test_cast_tensor_type():
    inputs = torch.rand(10)
    if torch.cuda.is_available():
        inputs = inputs.cuda()
    with pytest.raises(AssertionError):
        cast_tensor_type(inputs, src_type=None, dst_type=None)
    out = cast_tensor_type(10.0, dst_type=torch.half)
    assert out == 10.0 and isinstance(out, float)
    fp16_out = cast_tensor_type(inputs, dst_type=torch.half)
    assert fp16_out.dtype == torch.half
    fp32_out = cast_tensor_type(fp16_out, dst_type=torch.float32)
    assert fp32_out.dtype == torch.float32
    list_input = [inputs, inputs]
    list_outs = cast_tensor_type(list_input, dst_type=torch.half)
    assert len(list_outs) == len(list_input) and isinstance(list_outs, list)
    for out in list_outs:
        assert out.dtype == torch.half
    dict_input = {'test1': inputs, 'test2': inputs}
    dict_outs = cast_tensor_type(dict_input, dst_type=torch.half)
    assert len(dict_outs) == len(dict_input) and isinstance(dict_outs, dict)
    if torch.cuda.is_available():
        cpu_device = torch.empty(0).device
        gpu_device = inputs.device
        cpu_out = cast_tensor_type(inputs, dst_type=cpu_device)
        assert cpu_out.device == cpu_device
        gpu_out = cast_tensor_type(inputs, dst_type=gpu_device)
        assert gpu_out.device == gpu_device

def fpn_neck_config(test_step_name):
    """Return the class containing the corresponding attributes according to
    the fpn_test_step_names."""
    s = 64
    in_channels = [8, 16, 32, 64]
    feat_sizes = [s // 2 ** i for i in range(4)]
    out_channels = 8
    feats = [torch.rand(1, in_channels[i], feat_sizes[i], feat_sizes[i]) for i in range(len(in_channels))]
    if fpn_test_step_names[test_step_name] == 0:
        fpn_model = FPN(in_channels=in_channels, out_channels=out_channels, add_extra_convs=True, num_outs=5)
    elif fpn_test_step_names[test_step_name] == 1:
        fpn_model = FPN(in_channels=in_channels, out_channels=out_channels, add_extra_convs=False, num_outs=5)
    elif fpn_test_step_names[test_step_name] == 2:
        fpn_model = FPN(in_channels=in_channels, out_channels=out_channels, add_extra_convs=True, no_norm_on_lateral=False, norm_cfg=dict(type='BN', requires_grad=True), num_outs=5)
    elif fpn_test_step_names[test_step_name] == 3:
        fpn_model = FPN(in_channels=in_channels, out_channels=out_channels, add_extra_convs=True, upsample_cfg=dict(mode='bilinear', align_corners=True), num_outs=5)
    elif fpn_test_step_names[test_step_name] == 4:
        fpn_model = FPN(in_channels=in_channels, out_channels=out_channels, add_extra_convs=True, upsample_cfg=dict(scale_factor=2), num_outs=5)
    elif fpn_test_step_names[test_step_name] == 5:
        fpn_model = FPN(in_channels=in_channels, out_channels=out_channels, add_extra_convs='on_input', num_outs=5)
    elif fpn_test_step_names[test_step_name] == 6:
        fpn_model = FPN(in_channels=in_channels, out_channels=out_channels, add_extra_convs='on_lateral', num_outs=5)
    elif fpn_test_step_names[test_step_name] == 7:
        fpn_model = FPN(in_channels=in_channels, out_channels=out_channels, add_extra_convs='on_output', num_outs=5)
    return (fpn_model, feats)

def test_fpn_normal():
    outs = fpn_neck_config('fpn_normal')
    ort_validate(*outs)

